#include <iomanip>

int main() {
    int n = 0;
    std::cin >> n;
    double* px = new double[n];
    for (int i = 0; i < n; ++i) std::cin >> px[i];
    double total = 0;
    for (int i = 0; i < n; ++i) total += px[i];
    std::cout << std::fixed << std::setprecision(2) << total << "\n";
    delete[] px;
}

